@prefix schema1: <http://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a schema1:CreativeWork ;
                    schema1:name "HTTP" ] ;
            sh:resultMessage "A schema:CreativeWork should have a schema:url, an http(s), ftp(s), sftp, s3 or gs URL. Whether it resolves is not tested." ;
            sh:resultPath schema1:url ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:string ;
                    sh:message "A schema:CreativeWork should have a schema:url, an http(s), ftp(s), sftp, s3 or gs URL. Whether it resolves is not tested." ;
                    sh:minCount 1 ;
                    sh:path schema1:url ;
                    sh:pattern "^(https?|ftps?|sftp|s3|gs)://[^\\s]+$" ;
                    sh:severity sh:Warning ] ] .

